function NoteBox({ ticketId }) {
  const [notes, setNotes] = useState([]);
  const [draft, setDraft] = useState('');

  function addNote() {
    // WRONG: same array back means React sees no change.
    // notes.push({ id: crypto.randomUUID(), text: draft });
    // setNotes(notes);

    // RIGHT: a new array, built from the latest queued value.
    setNotes((current) => [...current, { id: `${ticketId}-${current.length}`, text: draft }]);
    setDraft('');
    console.log(draft); // still the OLD draft — this render's binding
  }

  return <button onClick={addNote}>Add note</button>;
}
```

Two things are worth staring at. `setNotes` is given a function, so if two notes are added in the same handler the second one sees the first one's result. And the `console.log` after `setDraft('')` prints the old draft, because `draft` is a `const` belonging to the render that is still running.

