solution.code:
function ticketReducer(state, action) {
  switch (action.type) {
    case 'add':
      return { ...state, tickets: [...state.tickets, action.ticket] };
    case 'resolve':
      return {
        ...state,
        tickets: state.tickets.map(function (ticket) {
          return ticket.id === action.id ? { ...ticket, status: 'resolved' } : ticket;
        }),
      };
    case 'remove':
      return { ...state, tickets: state.tickets.filter(t => t.id !== action.id) };
    default:
      return state;
  }
}

