solution.code:
function selectVisibleTickets(tickets, filters) {
  const query = filters.query.trim().toLowerCase();
  const matching = tickets.filter(function (ticket) {
    const subjectMatches = query === '' || ticket.subject.toLowerCase().includes(query);
    const statusMatches = filters.status === 'all' || ticket.status === filters.status;
    return subjectMatches && statusMatches;
  });
  const ordered = [...matching];
  ordered.sort(function (a, b) {
    return filters.sortBy === 'oldest' ? a.createdAt - b.createdAt : b.createdAt - a.createdAt;
  });
  return ordered;
}

